def transform(grid):
    if not grid:
        return grid

    # Background is 7 (based on task analysis)
    bg = 7

    # Find columns that contain at least one non-background value
    n_cols = len(grid[0])
    keep_cols_mask = [True] * n_cols
    for c in range(n_cols):
        for r in range(len(grid)):
            if grid[r][c] != bg:
                keep_cols_mask[c] = False
                break
        if keep_cols_mask[c]:
            keep_cols_mask[c] = True

    # Keep only these columns
    cropped = []
    for r in range(len(grid)):
        row = [grid[r][c] for c in range(n_cols) if keep_cols_mask[c]]
        cropped.append(row)

    # Sort rows by minimum non-background value
    def get_min_non_bg(row):
        non_bg = [v for v in row if v != bg]
        return (min(non_bg) if non_bg else 99)

    rows_data = [ (get_min_non_bg(row), r_idx, list(row)) for r_idx, row in enumerate(cropped) ]
    rows_data.sort(key=lambda x: (x[0], x[1]))

    return [row for _, _, row in rows_data]
